of these gradients are well-known, these functions make a good basis of a benchmark as they
perform typical operations that are commonly found inside more complicated functions (e.g.
+ , * , pow , exp inside loop).
double sum(double* p, int dim) {
double r = 0.0;
for (int i = 0; i < dim; i++)
r += p[i];
return r;
double mvn(double* x, double* p /*means*/,
double sigma, int dim) {
double t = 0;
for (int i = 0; i < dim; i++)
t += (x[i] - p[i])*(x[i] - p[i]);
t = -t / (2*sigma*sigma);
return std::pow(2*M_PI, -n/2.0) *
std::pow(sigma, -0.5) * std::exp(t);
